-- Insert Quiz Questions for Lesson: Conversations and Calendars

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'conversations-calendars' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson conversations-calendars not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the Conversations area do?', 
    '["Deletes all messages","Keeps supported messages together in one place","Only stores emails","Blocks all communication"]'::jsonb,
    'Keeps supported messages together in one place',
    'The Conversations area unifies communication channels so messages are not scattered across separate systems. Everything connects to the contact record.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can calendar bookings trigger?', 
    '["Nothing happens","Confirmation messages, reminders, workflow actions, opportunity updates, and internal notifications","Only deletion of the contact","Automatic payment only"]'::jsonb,
    'Confirmation messages, reminders, workflow actions, opportunity updates, and internal notifications',
    'Calendar bookings can trigger multiple automated actions: confirmations, reminders, workflows, opportunity updates, and notifications to your team.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important that conversations and calendars connect to contacts?', 
    '["It is not important","It creates a complete history of all interactions in one place","It makes the system slower","It costs extra money"]'::jsonb,
    'It creates a complete history of all interactions in one place',
    'When conversations and calendars connect to contacts, you get a complete history of all interactions in one place. This helps with context and follow-up.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
